def main():
    init_db()
    port = int(os.environ.get("PORT", 8804))
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    print(f"listening on http://127.0.0.1:{port}")
    server.serve_forever()


if __name__ == "__main__":
    main()
